-- Synthetic sample data. Run in GuestRegistrationCourse after 01_CreateTables.sql.
IF DB_NAME() <> N'GuestRegistrationCourse' AND DB_NAME() NOT LIKE N'GuestRegistrationTests[_]%'
    THROW 51000, 'Select the project database before seeding.', 1;
IF EXISTS (SELECT 1 FROM dbo.Users) OR EXISTS (SELECT 1 FROM dbo.BankCards) OR EXISTS (SELECT 1 FROM dbo.LoginAttempts)
BEGIN PRINT 'Seed skipped: the database is not empty.'; RETURN; END;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
SET IDENTITY_INSERT dbo.Users ON;
SET IDENTITY_INSERT dbo.Users OFF;
SET IDENTITY_INSERT dbo.BankCards ON;
SET IDENTITY_INSERT dbo.BankCards OFF;
SET IDENTITY_INSERT dbo.LoginAttempts ON;
SET IDENTITY_INSERT dbo.LoginAttempts OFF;
COMMIT TRANSACTION;
